import MindMap from './mindmap.svelte';
import MindMapControls from './mindmap-controls.svelte';

export { MindMap, MindMapControls };
export { useMindMap, MindMapContext } from './context.svelte.js';
export { getTheme } from './themes.js';
export type {
	MindMapData,
	MindMapInput,
	MindMapDirection,
	MindMapLocale,
	MindMapMarkdownParser,
	MindMapRef,
	MindMapTheme,
	MindMapControlsPosition,
	MindElixirData,
	MindElixirInstance,
	NodeObj,
	Options
} from './types.js';

export default MindMap;

import { getContext, setContext } from 'svelte';
import type { MindElixirInstance } from 'mind-elixir';

const MINDMAP_CONTEXT_KEY = Symbol('mindmapcn-svelte');

/** Reactive context shared between MindMap and child controls. */
export class MindMapContext {
	mind = $state<MindElixirInstance | null>(null);
	isLoaded = $state(false);
}

export function setMindMapContext(ctx: MindMapContext): MindMapContext {
	return setContext(MINDMAP_CONTEXT_KEY, ctx);
}

export function useMindMap(): MindMapContext {
	const ctx = getContext<MindMapContext | undefined>(MINDMAP_CONTEXT_KEY);
	if (!ctx) {
		throw new Error('useMindMap must be used within a MindMap component');
	}
	return ctx;
}

import { onMount } from 'svelte';

export type ResolvedTheme = 'light' | 'dark';

function getDocumentTheme(): ResolvedTheme | null {
	if (typeof document === 'undefined') return null;
	if (document.documentElement.classList.contains('dark')) return 'dark';
	if (document.documentElement.classList.contains('light')) return 'light';
	return null;
}

function getSystemTheme(): ResolvedTheme {
	if (typeof window === 'undefined') return 'light';
	return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
}

/**
 * Resolve light/dark theme from an explicit prop, document class, or system preference.
 * Mirrors mindmapcn-svelte's resolved-theme behavior (from the original mindmapcn design).
 */
export function createResolvedTheme(getThemeProp: () => ResolvedTheme | undefined) {
	let detected = $state<ResolvedTheme>(
		typeof document !== 'undefined' ? (getDocumentTheme() ?? getSystemTheme()) : 'light'
	);

	onMount(() => {
		const themeProp = getThemeProp();
		if (themeProp) return;

		const observer = new MutationObserver(() => {
			const docTheme = getDocumentTheme();
			if (docTheme) {
				detected = docTheme;
			}
		});
		observer.observe(document.documentElement, {
			attributes: true,
			attributeFilter: ['class']
		});

		const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
		const handleSystemChange = (e: MediaQueryListEvent) => {
			if (!getDocumentTheme()) {
				detected = e.matches ? 'dark' : 'light';
			}
		};
		mediaQuery.addEventListener('change', handleSystemChange);

		// Sync once on mount in case SSR default differed
		detected = getDocumentTheme() ?? getSystemTheme();

		return () => {
			observer.disconnect();
			mediaQuery.removeEventListener('change', handleSystemChange);
		};
	});

	return {
		get current(): ResolvedTheme {
			return getThemeProp() ?? detected;
		}
	};
}

import type { Theme as MindElixirTheme } from 'mind-elixir';

/** Common spacing and layout configuration shared by all themes. */
const commonSpacing = {
	'--node-gap-x': '48px',
	'--node-gap-y': '16px',
	'--main-gap-x': '24px',
	'--main-gap-y': '32px',
	'--root-radius': '0.625rem',
	'--main-radius': '0.5rem',
	'--topic-padding': '8px 16px',
	'--map-padding': '48px'
};

function createTheme(
	name: string,
	type: 'light' | 'dark',
	colors: {
		mainColor: string;
		mainBgcolor: string;
		color: string;
		bgcolor: string;
		selected: string;
		accentColor: string;
		rootColor: string;
		rootBgcolor: string;
		rootBorderColor: string;
		panelColor: string;
		panelBgcolor: string;
		panelBorderColor: string;
	},
	palette: string[]
): MindElixirTheme {
	return {
		name,
		type,
		palette,
		cssVar: {
			...commonSpacing,
			'--main-color': colors.mainColor,
			'--main-bgcolor': colors.mainBgcolor,
			'--main-bgcolor-transparent': `${colors.mainBgcolor.replace(')', ' / 95%)')}`,
			'--color': colors.color,
			'--bgcolor': colors.bgcolor,
			'--selected': colors.selected,
			'--accent-color': colors.accentColor,
			'--root-color': colors.rootColor,
			'--root-bgcolor': colors.rootBgcolor,
			'--root-border-color': colors.rootBorderColor,
			'--panel-color': colors.panelColor,
			'--panel-bgcolor': colors.panelBgcolor,
			'--panel-border-color': colors.panelBorderColor
		}
	};
}

const lightColors = {
	mainColor: 'oklch(0.145 0 0)', // foreground
	mainBgcolor: 'oklch(1 0 0)', // background (white)
	color: 'oklch(0.145 0 0)', // foreground
	bgcolor: 'oklch(1 0 0)', // card background
	selected: 'oklch(0.205 0 0)', // primary
	rootColor: 'oklch(0.985 0 0)', // primary-foreground
	rootBgcolor: 'oklch(0.205 0 0)', // primary
	rootBorderColor: 'oklch(0.205 0 0)', // primary
	panelColor: 'oklch(0.145 0 0)', // foreground
	panelBgcolor: 'oklch(1 0 0)', // popover
	panelBorderColor: 'oklch(0.922 0 0)' // border
};

const darkColors = {
	mainColor: 'oklch(0.985 0 0)', // foreground
	mainBgcolor: 'oklch(0.145 0 0)', // background (dark)
	color: 'oklch(0.985 0 0)', // foreground
	bgcolor: 'oklch(0.205 0 0)', // card background
	selected: 'oklch(0.922 0 0)', // primary
	rootColor: 'oklch(0.205 0 0)', // primary-foreground
	rootBgcolor: 'oklch(0.922 0 0)', // primary
	rootBorderColor: 'oklch(0.922 0 0)', // primary
	panelColor: 'oklch(0.985 0 0)', // foreground
	panelBgcolor: 'oklch(0.205 0 0)', // popover
	panelBorderColor: 'oklch(1 0 0 / 10%)' // border
};

const lightTheme: MindElixirTheme = createTheme(
	'shadcn-light',
	'light',
	{
		...lightColors,
		accentColor: 'oklch(0.646 0.222 41.116)' // chart-1 (vibrant)
	},
	[
		'oklch(0.646 0.222 41.116)', // chart-1: vibrant orange
		'oklch(0.6 0.118 184.704)', // chart-2: teal
		'oklch(0.398 0.07 227.392)', // chart-3: blue
		'oklch(0.828 0.189 84.429)', // chart-4: yellow-green
		'oklch(0.769 0.188 70.08)', // chart-5: warm yellow
		'oklch(0.488 0.243 264.376)', // purple
		'oklch(0.696 0.17 162.48)' // mint
	]
);

const darkTheme: MindElixirTheme = createTheme(
	'shadcn-dark',
	'dark',
	{
		...darkColors,
		accentColor: 'oklch(0.488 0.243 264.376)' // chart-1 (purple)
	},
	[
		'oklch(0.488 0.243 264.376)', // chart-1: purple
		'oklch(0.696 0.17 162.48)', // chart-2: mint
		'oklch(0.769 0.188 70.08)', // chart-3: warm yellow
		'oklch(0.627 0.265 303.9)', // chart-4: pink
		'oklch(0.645 0.246 16.439)', // chart-5: coral
		'oklch(0.646 0.222 41.116)', // orange
		'oklch(0.6 0.118 184.704)' // teal
	]
);

const lightThemeMonochrome: MindElixirTheme = createTheme(
	'shadcn-light-mono',
	'light',
	{
		...lightColors,
		accentColor: 'oklch(0.205 0 0)' // primary
	},
	['oklch(0.205 0 0)']
);

const darkThemeMonochrome: MindElixirTheme = createTheme(
	'shadcn-dark-mono',
	'dark',
	{
		...darkColors,
		accentColor: 'oklch(0.922 0 0)' // primary
	},
	['oklch(0.922 0 0)']
);

/** Resolve the shadcn-styled Mind Elixir theme. */
export function getTheme(isDark: boolean, isMonochrome: boolean): MindElixirTheme {
	if (isDark) {
		return isMonochrome ? darkThemeMonochrome : darkTheme;
	}
	return isMonochrome ? lightThemeMonochrome : lightTheme;
}

import type { MindElixirData, MindElixirInstance, NodeObj, Options } from 'mind-elixir';

/** Custom markdown parser — same signature as Mind Elixir `Options.markdown`. */
export type MindMapMarkdownParser = NonNullable<Options['markdown']>;

export type MindMapData = MindElixirData;

/**
 * Accepted data input for the MindMap component.
 * Either a `MindElixirData` object or a Mind Elixir plaintext string
 * (indentation-based outline that is parsed via `plaintextToMindElixir`).
 */
export type MindMapInput = MindElixirData | string;

export type MindMapLocale = 'en' | 'zh_CN' | 'zh_TW' | 'ja' | 'pt';

export type MindMapDirection = 0 | 1 | 2;

export type MindMapTheme = 'light' | 'dark';

export type MindMapControlsPosition = 'top-left' | 'top-right' | 'bottom-left' | 'bottom-right';

/** Imperative handle exposed via bind:this on MindMap. */
export interface MindMapRef {
	readonly instance: MindElixirInstance | null;
	readonly isLoaded: boolean;
}

export type { MindElixirData, MindElixirInstance, NodeObj, Options };
